import net.minecraftforge.fml.common.Mod;
import yesman.epicfight.api.forgeevent.WeaponCapabilityPresetRegistryEvent;
import yesman.epicfight.gameasset.ColliderPreset;
import yesman.epicfight.gameasset.EpicFightSounds;
import yesman.epicfight.particle.EpicFightParticles;
import yesman.epicfight.particle.HitParticleType;
import yesman.epicfight.world.capabilities.item.CapabilityItem;
import yesman.epicfight.world.capabilities.item.Style;
import yesman.epicfight.world.capabilities.item.WeaponCategory;

@Mod.EventBusSubscriber(modid="invincible", bus=Mod.EventBusSubscriber.Bus.MOD)
public class InvincibleDemoWeaponCapabilityPresets {
    public static final Function<Item, CapabilityItem.Builder> DEMO = item -> ComboWeaponCapability.builder().category((WeaponCategory)CapabilityItem.WeaponCategories.SWORD).styleProvider(entityPatch -> CapabilityItem.Styles.COMMON).collider(ColliderPreset.SWORD).swingSound((SoundEvent)EpicFightSounds.WHOOSH.get()).hitSound((SoundEvent)EpicFightSounds.BLADE_HIT.get()).hitParticle((HitParticleType)EpicFightParticles.HIT_BLADE.get()).canBePlacedOffhand(false).innateSkill((Style)CapabilityItem.Styles.COMMON, itemstack -> InvincibleDemoSkills.COMBO_DEMO).comboCancel(style -> false);

    @SubscribeEvent
    public static void register(WeaponCapabilityPresetRegistryEvent event) {
        event.getTypeEntry().put(ResourceLocation.fromNamespaceAndPath((String)"invincible", (String)"demo"), DEMO);
    }
}

