private Influence parseEnchantmentList(String enchantmentList) {
    String[] enchantments;
    ArrayList<Enchantment> boost = new ArrayList<Enchantment>();
    ArrayList<Enchantment> dampen = new ArrayList<Enchantment>();
    for (String enchStr : enchantments = enchantmentList.split(",")) {
        Enchantment ench;
        boolean damp = enchStr.startsWith("-");
        if (damp) {
            enchStr = enchStr.substring(1);
        }
        if ((ench = (Enchantment)BuiltInRegistries.f_256876_.m_7745_(new ResourceLocation(enchStr))) != null) {
            if (damp) {
                dampen.add(ench);
                continue;
            }
            boost.add(ench);
            continue;
        }
        Quark.LOG.error("Matrix Enchanting Influencing: Enchantment " + enchStr + " does not exist!");
    }
    return new Influence(boost, dampen);
}

